// pubspec.yaml:
//   firebase_analytics: ^10.7.0

import 'package:firebase_analytics/firebase_analytics.dart';
import 'package:firebase_analytics/observer.dart';

final analytics = FirebaseAnalytics.instance;

// 1. Wire the navigator observer — one line, gets you free screen_view events.
MaterialApp(
  navigatorObservers: [FirebaseAnalyticsObserver(analytics: analytics)],
  // ...
);

// 2. Custom events — snake_case, ≤ 40 chars, small stable set.
await analytics.logEvent(
  name: 'add_to_cart',
  parameters: {
    'item_id': '42',
    'item_name': 'Widget',
    'currency': 'INR',
    'value': 199,
    'variant': 'red',
  },
);

// 3. E-commerce standard events — Firebase understands these natively.
await analytics.logPurchase(
  currency: 'INR',
  value: 299,
  transactionId: 'txn_123',
  items: [AnalyticsEventItem(itemId: '42', itemName: 'Widget', price: 299)],
);

// 4. User properties — persistent, sliceable in every report.
await analytics.setUserProperty(name: 'plan', value: 'pro');
await analytics.setUserProperty(name: 'signup_channel', value: 'organic');

// 5. User ID (pseudonymous — YOUR internal UID, NOT email or phone).
await analytics.setUserId(id: user.uid);

// 6. Consent Mode (GDPR / DPDPA compliance).
await analytics.setConsent(
  analyticsStorageConsentGranted: consent.analytics,
  adStorageConsentGranted: consent.ads,
);

// 7. Disable collection entirely for opt-out users.
await analytics.setAnalyticsCollectionEnabled(consent.analytics);

// 8. Debug — see events in real time in Firebase console DebugView:
// adb shell setprop debug.firebase.analytics.app com.example.app
// (iOS) run with -FIRDebugEnabled Xcode arg.
